    pub fn speak(&self, text: String) -> Result<(), reqwest::Error> {
        let url = format!("https://api.elevenlabs.io/v1/speak?api_key={}&text={}", self.api_key, text);
        let res = reqwest::get(url).await?;
        let response: SpeakResponse = res.json().await?;
